import py_compile

class SelfConsistency:
    def generate_multiple(self, task_text, call_llm_func, n=3):
        variants = []
        temperatures = [0.2, 0.5, 0.8]

        for temp in temperatures:
            response = call_llm_func(task_text, temperature=temp)
            code_blocks = self.extract_code_blocks(response)
            variants.extend(code_blocks)

        return variants

    def extract_code_blocks(self, response):
        # Примерная реализация извлечения блоков кода
        code_blocks = []
        for line in response.split('\n'):
            if '```python' in line:
                code_block = ''
                while True:
                    line = next(response)
                    if '```' in line:
                        break
                    code_block += line + '\n'
                code_blocks.append(code_block.strip())
        return code_blocks

    def vote(self, variants, verify_func):
        results = {'valid': [], 'invalid': []}
        for variant in variants:
            try:
                py_compile.compile(variant)
                results['valid'].append(variant)
            except py_compile.PyCompileError:
                results['invalid'].append(variant)
        return results

    def select_best(self, variants):
        if not variants:
            return None

        # Sort variants by length in descending order
        sorted_variants = sorted(variants, key=len, reverse=True)

        # Return the first variant from the sorted list
        return sorted_variants[0]

    def consensus(self, task_text, call_llm_func, verify_func):
        variants = self.generate_multiple(task_text, call_llm_func)
        vote_results = self.vote(variants, verify_func)
        best_variant = self.select_best(vote_results['valid'])

        confidence = len(vote_results['valid']) / len(variants) if variants else 0
        return {
            'code': best_variant,
            'attempts': len(variants),
            'valid_count': len(vote_results['valid']),
            'confidence': confidence
        }

