class SelfConsistency:
    def generate_multiple(self, task, llm_func, n=3):
        variants = []
        for _ in range(n):
            response = llm_func(task)
            code_blocks = self.extract_code_blocks(response)
            variants.extend(code_blocks)
        return variants

    def extract_code_blocks(self, response):
        # Примерная реализация извлечения блоков кода
        import re
        code_blocks = re.findall(r'```(.*?)```', response, re.DOTALL)
        return code_blocks

    def vote(self, variants, verify_func):
        votes = {}
        for variant in variants:
            if verify_func(variant):
                votes[variant] = votes.get(variant, 0) + 1
        return max(votes, key=votes.get)

    def select_best(self, valid):
        # Примерная реализация выбора лучшего варианта
        return sorted(valid, key=len)[0]

    def consensus(self, task, llm_func, verify_func):
        variants = self.generate_multiple(task, llm_func)
        valid = [variant for variant in variants if verify_func(variant)]
        if not valid:
            return None
        best_variant = self.select_best(valid)
        return best_variant

