def deep_merge(dict1, dict2):
    for key in dict2:
        if key in dict1 and isinstance(dict1[key], dict) and isinstance(dict2[key], dict):
            deep_merge(dict1[key], dict2[key])
        else:
            dict1[key] = dict2[key]
    return dict1

class StateMachine:
    def __init__(self):
        self.states = {}
        self.transitions = {}

    def add_state(self, name):
        if name not in self.states:
            self.states[name] = []
            print(f"State '{name}' added.")
        else:
            print(f"State '{name}' already exists.")

    def transition(self, from_state, to_state, event):
        if from_state in self.states and to_state in self.states:
            if (from_state, event) not in self.transitions:
                self.transitions[(from_state, event)] = to_state
                print(f"Transition from '{from_state}' to '{to_state}' on event '{event}' added.")
            else:
                print(f"Transition from '{from_state}' on event '{event}' already exists and goes to '{self.transitions[(from_state, event)]}'.")
        else:
            print("One or both states do not exist.")

