class TCPClient:
    def __init__(self):
        self.socket = None

    def connect(self, host, port):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.connect((host, port))

    def send(self, data):
        if self.socket is None:
            raise Exception("Not connected")
        self.socket.sendall(data.encode())

    def receive(self):
        if self.socket is None:
            raise Exception("Not connected")
        return self.socket.recv(4096).decode()

    def close(self):
        if self.socket is not None:
            self.socket.close()
            self.socket = None

from collections import OrderedDict

class LRUCache:
    def __init__(self, max_size):
        self.max_size = max_size
        self.cache = OrderedDict()

    def get(self, key):
        """Возвращает значение по ключу и перемещает его в конец очереди."""
        if key not in self.cache:
            return None
        else:
            value = self.cache[key]
            self.cache.move_to_end(key)
            return value

    def put(self, key, val):
        """Устанавливает значение по ключу и перемещает его в конец очереди.
        Если кеш достиг максимального размера, удаляет наименее недавно используемый элемент."""
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) >= self.max_size:
            self.cache.popitem(last=False)
        self.cache[key] = val

