import socket

class PacketSniffer:
    def __init__(self):
        self.socket = None
        self.running = False

    def start(self, callback):
        if self.running:
            raise RuntimeError("Packet sniffer is already running")

        self.socket = socket.socket(socket.AF_PACKET, socket.SOCK_RAW, socket.ntohs(0x0003))
        self.running = True

        while self.running:
            packet = self.socket.recvfrom(65535)
            callback(packet)

    def stop(self):
        if not self.running:
            raise RuntimeError("Packet sniffer is not running")

        self.running = False
        self.socket.close()

