        self.buffer = [None] * size
        self.start = 0
        self.end = 0
        self.full = False

    def write(self, data):
        if self.full:
            self.start = (self.start + 1) % self.size
        self.buffer[self.end] = data
        self.end = (self.end + 1) % self.size
        if self.end == self.start:
