import subprocess

class ProcessPool:
    def __init__(self):
        self.processes = []

    def submit(self, cmd):
        # Convert the command to a list of arguments to avoid shell=True security issues
        if isinstance(cmd, str):
            import shlex
            cmd = shlex.split(cmd)

        process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        self.processes.append(process)

    def get_results(self):
        results = []
        for process in self.processes[:]:
            # Wait for the process to complete before retrieving results
            stdout, stderr = process.communicate()
            results.append((stdout.decode(), stderr.decode()))
        # Clear the list of processes after all have been completed
        self.processes.clear()
        return results

