import subprocess

class ProcessPool:
    def __init__(self):
        self.processes = []

    def submit(self, cmd):
        # Используем список аргументов вместо shell=True для повышения безопасности
        process = subprocess.Popen(cmd.split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        self.processes.append(process)

    def get_results(self):
        results = []
        for process in self.processes[:]:
            if process.poll() is not None:
                stdout, stderr = process.communicate()
                results.append((stdout.decode(), stderr.decode()))
            else:
                # Если процесс еще не завершен, добавляем его обратно в список
                results.append(None)
        # Оставляем только те процессы, которые еще не завершены
        self.processes = [process for process in self.processes if process.poll() is None]
        return results

