import time
import random

def observer(max_retries=5, base_delay=1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Attempt {attempts + 1} failed: {e}")
                    delay = base_delay * (2 ** attempts) + random.uniform(0, 0.5)
                    time.sleep(delay)
                    attempts += 1
            raise Exception("Max retries exceeded")
        return wrapper
    return decorator

