import itertools

class SplitError(Exception):
    """Базовое исключение для ошибок в функции splitter."""
    pass

class EmptyStringError(SplitError):
    """Исключение, возникающее при попытке разделить пустую строку."""
    pass

class InvalidDelimiterError(SplitError):
    """Исключение, возникающее при использовании недопустимого разделителя."""
    pass

def splitter(data: str, delimiter: str) -> list:
    if not data:
        raise EmptyStringError("Строка не может быть пустой")
    if not delimiter:
        raise InvalidDelimiterError("Разделитель не может быть пустым")

    # Используем itertools.groupby для разделения строки
    split_data = []
    current_chunk = []

    for char in data:
        if char == delimiter:
            if current_chunk:
                split_data.append(''.join(current_chunk))
                current_chunk = []
        else:
            current_chunk.append(char)

    # Добавляем последний фрагмент, если он существует
    if current_chunk:
        split_data.append(''.join(current_chunk))

    return split_data

# Пример использования:
