import subprocess

def resolver(input_list, command):
    filtered_list = []

    for item in input_list:
        try:
            result = subprocess.run(command + [item], capture_output=True, text=True, check=True)
            if result.stdout.strip():
                filtered_list.append(item)
        except subprocess.CalledProcessError as e:
            print(f"Failed to process {item}: {e.stderr}")

    return filtered_list

