from typing import Any, Dict

class HttpAPIMock:
    def __init__(self):
        self.data: Dict[str, Any] = {}

    def request(self, method: str, endpoint: str, params: Dict[str, Any] = None) -> Any:
        if method == "GET":
            return self._get(endpoint)
        elif method == "POST":
            return self._post(endpoint, params)
        else:
            raise ValueError(f"Unknown method: {method}")

    def _get(self, endpoint: str) -> Any:
        if endpoint in self.data:
            return self.data[endpoint]
        else:
            raise KeyError(f"Endpoint not found: {endpoint}")

    def _post(self, endpoint: str, params: Dict[str, Any]) -> Any:
        if endpoint is None or params is None:
            raise ValueError("Endpoint and params must be provided for POST request")
        self.data[endpoint] = params
        return {"status": "success", "data": params}

import time

def converter(max_retries=3, delay=1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except (IOError, OSError) as e:
                    print(f"Attempt {attempts + 1} failed: {e}")
                    time.sleep(delay)
                    attempts += 1
            raise Exception("Max retries exceeded")
        return wrapper
    return decorator

