from sortedcontainers import SortedSet
from threading import Lock

class ThreadSafeTreeSet:
    def __init__(self):
        self._set: SortedSet = SortedSet()
        self._lock: Lock = Lock()

    def add(self, item: any) -> None:
        """Добавляет элемент в TreeSet."""
        if item is None:
            raise ValueError("Item cannot be None")
        with self._lock:
            self._set.add(item)

    def remove(self, item: any) -> bool:
        """Удаляет элемент из TreeSet."""
        if item is None:
            return False
        with self._lock:
            return self._set.remove(item)

    def contains(self, item: any) -> bool:
        """Проверяет наличие элемента в TreeSet."""
        with self._lock:
            return item in self._set

    def size(self) -> int:
        """Возвращает количество элементов в TreeSet."""
        with self._lock:
            return len(self._set)

class TestThreadSafeTreeSet(unittest.TestCase):
    def setUp(self):
        self.tree_set = ThreadSafeTreeSet()

    def test_add_and_remove(self):
        self.tree_set.add(1)
        self.assertTrue(self.tree_set.contains(1))
        self.assertTrue(self.tree_set.remove(1))
        self.assertFalse(self.tree_set.contains(1))

    def test_size(self):
        self.assertEqual(self.tree_set.size(), 0)
        self.tree_set.add(1)
        self.assertEqual(self.tree_set.size(), 1)
        self.tree_set.add(2)
        self.assertEqual(self.tree_set.size(), 2)

    def test_remove_nonexistent_item(self):
        self.assertFalse(self.tree_set.remove(1))

    def test_add_none(self):
        with self.assertRaises(ValueError):
            self.tree_set.add(None)

if __name__ == '__main__':
    unittest.main()

