def splitter(data, delimiter):
    """
    Разделяет данные на части через генератор.

    Пример использования:
    for part in splitter(some_data, some_delimiter):
        print(part)
    """
    try:
        buffer = ""
        for char in data:
            if char == delimiter:
                yield buffer
                buffer = ""
            else:
                buffer += char
        yield buffer  # Выдать оставшуюся часть
    except Exception as e:
        print(f"Ошибка при разделении данных: {e}")

from collections import deque
from threading import Lock

class ThreadSafeRingBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self._buffer = deque(maxlen=capacity)
        self._lock = Lock()

    def put(self, item: any) -> None:
        """Добавляет элемент в буфер."""
        with self._lock:
            self._buffer.append(item)

    def get(self) -> any:
        """Извлекает и возвращает элемент из буфера."""
        with self._lock:
            if not self._buffer:
                raise IndexError("Buffer is empty")
            return self._buffer.popleft()

    def peek(self) -> any:
        """Возвращает следующий элемент без его удаления."""
        with self._lock:
            if not self._buffer:
                raise IndexError("Buffer is empty")
            return self._buffer[0]

    def size(self) -> int:
        """Возвращает текущий размер буфера."""
        with self._lock:
            return len(self._buffer)

    def capacity(self) -> int:
        """Возвращает максимальную емкость буфера."""
        return self._buffer.maxlen

    def clear(self) -> None:
        """Очищает буфер."""
        with self._lock:
            self._buffer.clear()

