from typing import Any, TypeVar

T = TypeVar('T')

class TreeSet:
    def __init__(self):
        self._elements: list[T] = []  # Добавлен type hint

    def add(self, item: T) -> None:
        """Добавляет элемент в TreeSet."""
        if item is None:
            raise ValueError("Item cannot be None")
        self._elements.append(item)
        self._elements.sort()

    def remove(self, item: T) -> bool:
        """Удаляет элемент из TreeSet."""
        try:
            self._elements.remove(item)
            return True
        except ValueError:
            return False

    def contains(self, item: T) -> bool:
        """Проверяет наличие элемента в TreeSet."""
        return item in self._elements

    def size(self) -> int:
        """Возвращает количество элементов в TreeSet."""
        return len(self._elements)

    def __iter__(self):
        return iter(self._elements)

from typing import List, Optional

class TreeNode:
    def __init__(self, value: int):
        self.value = value
        self.left: Optional[TreeNode] = None
        self.right: Optional[TreeNode] = None

def dfs_traversal(root: Optional[TreeNode]) -> List[int]:
    """
    Функция для обхода дерева в глубину (DFS).

    :param root: Корень дерева.
    :return: Список значений узлов в порядке обхода DFS.
    """
    if not isinstance(root, TreeNode) and root is not None:
        raise TypeError("Аргумент должен быть экземпляром TreeNode или None.")

    result = []

    def traverse(node: Optional[TreeNode]):
        if node is None:
            return
        result.append(node.value)
        traverse(node.left)
        traverse(node.right)

    try:
        traverse(root)
    except Exception as e:
        print(f"Произошла ошибка при обходе дерева: {e}")

    return result

from functools import lru_cache

class MemoizedIterator:
    def __init__(self, data):
        self.data = data
        self.index = 0
        self.memo = {}

    def __iter__(self):
        return self

    @lru_cache(maxsize=None)
    def _get_item(self, index):
        return self.data[index]

    def __next__(self):
        if self.index >= len(self.data):
            raise StopIteration
        result = self._get_item(self.index)
        self.index += 1
        return result

