import hashlib

def parser(data, format_from, format_to):
    try:
        # Создание объекта hash на основе исходного формата
        if format_from == 'md5':
            hash_obj = hashlib.md5()
        elif format_from == 'sha1':
            hash_obj = hashlib.sha1()
        elif format_from == 'sha256':
            hash_obj = hashlib.sha256()
        else:
            raise ValueError(f"Неподдерживаемый исходный формат: {format_from}")

        # Обновление объекта hash данными
        hash_obj.update(data.encode('utf-8'))

        # Получение хеша в указанном формате
        if format_to == 'hex':
            return hash_obj.hexdigest()
        elif format_to == 'bytes':
            return hash_obj.digest()
        else:
            raise ValueError(f"Неподдерживаемый целевой формат: {format_to}")

    except Exception as e:
        print(f"Ошибка при конвертации данных: {e}")
        raise

class Observer:
    def __init__(self):
        self.items = []

    def push(self, item):
        """Добавляет элемент в наблюдателя."""
        self.items.append(item)

    def pop(self):
        """Удаляет и возвращает последний добавленный элемент. Возвращает None, если наблюдатель пуст."""
        if not self.is_empty():
            return self.items.pop()
        return None

    def peek(self):
        """Возвращает последний добавленный элемент без его удаления. Возвращает None, если наблюдатель пуст."""
        if not self.is_empty():
            return self.items[-1]
        return None

    def is_empty(self):
        """Проверяет, пуст ли наблюдатель."""
        return len(self.items) == 0

