import unittest
from TreeSet import ThreadSafeTreeSet

class TestThreadSafeTreeSet(unittest.TestCase):
    def setUp(self):
        self.tree_set = ThreadSafeTreeSet()

    def test_add_single_element(self):
        self.tree_set.add(1)
        self.assertIn(1, self.tree_set._set)

    def test_remove_existing_element(self):
        self.tree_set.add(1)
        self.assertTrue(self.tree_set.remove(1))
        self.assertNotIn(1, self.tree_set._set)

    def test_remove_non_existing_element(self):
        self.assertFalse(self.tree_set.remove(1))

    def test_add_none(self):
        with self.assertRaises(ValueError):
            self.tree_set.add(None)

    def test_add_multiple_elements(self):
        elements = [5, 3, 8, 1, 9]
        for elem in elements:
            self.tree_set.add(elem)
        for elem in elements:
            self.assertIn(elem, self.tree_set._set)

    def test_remove_all_elements(self):
        elements = [5, 3, 8, 1, 9]
        for elem in elements:
            self.tree_set.add(elem)
        for elem in elements:
            self.assertTrue(self.tree_set.remove(elem))
        self.assertEqual(len(self.tree_set._set), 0)

    def test_thread_safety_add(self):
        import threading

        def add_element():
            for _ in range(100):
                self.tree_set.add(1)

        threads = [threading.Thread(target=add_element) for _ in range(10)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

        self.assertEqual(len(self.tree_set._set), 1)

    def test_thread_safety_remove(self):
        import threading

        elements = list(range(100))
        for elem in elements:
            self.tree_set.add(elem)

        def remove_element():
            for _ in range(100):
                self.tree_set.remove(1)

        threads = [threading.Thread(target=remove_element) for _ in range(10)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

        self.assertNotIn(1, self.tree_set._set)

