class Singleton:
    _instance = None
    _values = []

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(Singleton, cls).__new__(cls)
        return cls._instance

    @classmethod
    def add(cls, value):
        try:
            if value not in cls._values:
                cls._values.append(value)
        except Exception as e:
            print(f"Error adding value: {e}")

    @classmethod
    def remove(cls, value):
        try:
            if value in cls._values:
                cls._values.remove(value)
        except Exception as e:
            print(f"Error removing value: {e}")

    @classmethod
    def find(cls, value):
        try:
            return value in cls._values
        except Exception as e:
            print(f"Error finding value: {e}")
            return False

