from typing import Any, Optional

class ParserError(Exception):
    """Базовое исключение для ошибок парсера."""
    pass

class InvalidDataError(ParserError):
    """Исключение для некорректных данных."""
    pass

class Parser:
    def __init__(self) -> None:
        self.data: Optional[Any] = None

    def load(self, data: Any) -> None:
        """
        Загрузка данных.
        :param data: Данные для загрузки
        """
        try:
            self.validate(data)
            self.data = data
        except InvalidDataError as e:
            raise ParserError(f"Ошибка при загрузке данных: {e}")

    def save(self) -> Any:
        """
        Сохранение данных.
        :return: Загруженные данные
        """
        if self.data is None:
            raise ParserError("Данные не были загружены")
        return self.data

    def validate(self, data: Any) -> None:
        """
        Валидация данных.
        :param data: Данные для валидации
        """
        if not isinstance(data, dict):
            raise InvalidDataError("Данные должны быть словарем")
        if not data:
            raise InvalidDataError("Словарь не должен быть пустым")

class OptimizedValidator:
    def __init__(self, data):
        self.data = data

    def validate(self, condition_func):
        try:
            filtered_data = filter(condition_func, self.data)
            mapped_data = map(lambda x: (x, True), filtered_data)
            return list(mapped_data)
        except Exception as e:
            print(f"Error during validation: {e}")
            return []

