from abc import ABC, abstractmethod

class Observer(ABC):
    @abstractmethod
    def start(self) -> None:
        pass

    @abstractmethod
    def stop(self) -> None:
        pass

    @abstractmethod
    def status(self) -> str:
        pass

class ConcreteObserverA(Observer):
    def __init__(self):
        self._running = False

    def start(self) -> None:
        if not self._running:
            self._running = True
            print("ConcreteObserverA started")
        else:
            print("ConcreteObserverA is already running")

    def stop(self) -> None:
        if self._running:
            self._running = False
            print("ConcreteObserverA stopped")
        else:
            print("ConcreteObserverA is not running")

    def status(self) -> str:
        return "Running" if self._running else "Stopped"

class SplitterError(Exception):
    """Базовое исключение для ошибок разделителя."""
    pass

class EmptyStringError(SplitterError):
    """Исключение для пустой строки при разделении."""
    pass

class InvalidDelimiterError(SplitterError):
    """Исключение для некорректного разделителя."""
    pass

class Splitter:
    def __init__(self, delimiter: str) -> None:
        if not delimiter:
            raise InvalidDelimiterError("Разделитель не может быть пустым.")
        self.delimiter = delimiter

    def split(self, text: str) -> list[str]:
        """
        Разделение строки по заданному разделителю.
        """
        try:
            if not text:
                raise EmptyStringError("Строка для разделения не может быть пустой.")
            return text.split(self.delimiter)
        except Exception as e:
            raise SplitterError(f"Ошибка при разделении: {e}") from e

