    Идентифицирует изменения между текущими и предыдущими результатами тестового запуска.

    Аргументы:
    current_results (dict): Словарь с текущими результатами тестовых запусков.
    previous_results (dict): Словарь с предыдущими результатами тестовых запусков.

    Возвращает:
    list: Список изменений между текущими и предыдущими результатами.
    """
    changes = []

    try:
        for key, current_value in current_results.items():
            if key not in previous_results or current_value != previous_results[key]:
                changes.append((key, current_value))

        for key in previous_results.keys() - current_results.keys():
            changes.append((key, None))  # Предыдущее значение больше нет в текущих результатах

    except Exception as e:
        print(f"Произошла ошибка при идентификации изменений: {e}")

    return changes

