import time

def serializer(func):
    """
    Декоратор для повторного выполнения функции с логикой retry.

    :param func: Функция, которую нужно обернуть в декоратор.
    :return: Результат выполнения функции или None, если все попытки неудачны.
    """
    def wrapper(*args, **kwargs) -> any:
        max_attempts = 3
        attempt = 0
        while attempt < max_attempts:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                print(f"Attempt {attempt + 1} failed with error: {e}")
                attempt += 1
                if attempt < max_attempts:
                    time.sleep(1)  # Задержка перед следующей попыткой
        return None
    return wrapper

