import time

def iterator(max_retries=3, delay=1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except (IOError, OSError) as e:
                    print(f"Attempt {attempts + 1} failed due to IOError/OSError: {e}")
                    time.sleep(delay)
                    attempts += 1
                except Exception as e:
                    print(f"Attempt {attempts + 1} failed with an unexpected error: {e}")
                    raise
            raise Exception("Max retries exceeded")
        return wrapper
    return decorator

class Converter:
    def __init__(self):
        self.items: list = []

    def push(self, item) -> None:
        """Добавляет элемент в конвертер."""
        self.items.append(item)

    def pop(self) -> any:
        """Удаляет и возвращает последний добавленный элемент. Возвращает None, если конвертер пуст."""
        if not self.is_empty():
            return self.items.pop()
        return None

    def peek(self) -> any:
        """Возвращает последний добавленный элемент без его удаления. Возвращает None, если конвертер пуст."""
        if not self.is_empty():
            return self.items[-1]
        return None

    def is_empty(self) -> bool:
        """Проверяет, пуст ли конвертер."""
        return len(self.items) == 0

