def integrate_results(current_results: dict, previous_results: dict) -> dict:
    """
    Интегрирует данные из текущих результатов и предыдущих тестовых запусков в отчет.

    Аргументы:
    current_results (dict): Словарь с текущими результатами.
    previous_results (dict): Словарь с результатами предыдущего тестового запуска.

    Возвращает:
    dict: Интегрированный отчет с данными из обоих наборов результатов.
    """
    try:
        integrated_report = {}

        # Объединяем общие ключи
        for key in current_results.keys() & previous_results.keys():
            if isinstance(current_results[key], dict) and isinstance(previous_results[key], dict):
                integrated_report[key] = {**previous_results[key], **current_results[key]}
            else:
                integrated_report[key] = (previous_results[key], current_results[key])

        # Добавляем уникальные ключи
        for key in current_results.keys() - previous_results.keys():
            integrated_report[key] = current_results[key]

        for key in previous_results.keys() - current_results.keys():
            integrated_report[key] = previous_results[key]

        return integrated_report

    except Exception as e:
        print(f"Ошибка при интеграции результатов: {e}")
        return {}

import time

def iterator(max_retries=3, delay=1, error_handlers=None):
    if error_handlers is None:
        error_handlers = {}

    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    handler = error_handlers.get(type(e), lambda x: print(f"Attempt {attempts + 1} failed: {x}"))
                    handler(e)
                    time.sleep(delay)
                    attempts += 1
            raise Exception("Max retries exceeded")
        return wrapper
    return decorator

