            data = json.load(file)

        # Определяем тип данных
        if isinstance(data, list):
            structure_type = "list"
            element_structure = [str(type(item)) for item in data[:5]]  # Проверяем первые 5 элементов
        elif isinstance(data, dict):
            structure_type = "dict"
            element_structure = {key: str(type(value)) for key, value in list(data.items())[:5]}  # Проверяем первые 5 ключей
        else:
            structure_type = "unknown"
            element_structure = {}

        return {
            "structure_type": structure_type,
            "element_structure": element_structure
        }
    except Exception as e:
        return {"error": str(e)}

