from typing import Any, Optional

class ValidatorError(Exception):
    """Базовое исключение для ошибок валидатора."""
    pass

class InvalidDataError(ValidatorError):
    """Исключение для некорректных данных."""
    pass

class Validator:
    def __init__(self) -> None:
        self.data: Optional[Any] = None

    def load(self, data: Any) -> None:
        """
        Загрузка данных.
        :param data: Данные для загрузки
        """
        try:
            self.validate(data)
            self.data = data
        except InvalidDataError as e:
            print(f"Ошибка при загрузке данных: {e}")

    def save(self) -> Any:
        """
        Сохранение данных.
        :return: Загруженные данные
        """
        if self.data is None:
            raise ValidatorError("Данные не были загружены.")
        return self.data

    def validate(self, data: Any) -> None:
        """
        Валидация данных.
        :param data: Данные для валидации
        """
        if not isinstance(data, dict):
            raise InvalidDataError("Данные должны быть словарем.")
        if "required_key" not in data:
            raise InvalidDataError("Отсутствует обязательный ключ 'required_key'.")

class MemoryEfficientObserver:
    __slots__ = ('subscribers',)

    def __init__(self):
        self.subscribers = []

    def subscribe(self, subscriber: callable):
        self.subscribers.append(subscriber)

    def unsubscribe(self, subscriber: callable):
        self.subscribers.remove(subscriber)

    def notify(self, *args, **kwargs):
        for subscriber in self.subscribers:
            try:
                subscriber(*args, **kwargs)
            except Exception as e:
                print(f"Error notifying subscriber: {e}")

