class SerializeError(Exception):
    """Базовое исключение для ошибок в классе Serializer."""
    pass

class InvalidDataError(SerializeError):
    """Исключение, возникающее при попытке сериализации некорректных данных."""
    pass

class FormatNotSupportedError(SerializeError):
    """Исключение, возникающее при использовании неподдерживаемого формата."""
    pass

class Serializer:
    def __init__(self, format: str):
        self.format = format
        if format not in ['json', 'xml']:
            raise FormatNotSupportedError(f"Формат {format} не поддерживается")

    def serialize(self, data) -> str:
        try:
            if self.format == 'json':
                import json
                return json.dumps(data)
            elif self.format == 'xml':
                from dicttoxml import dicttoxml
                return dicttoxml(data).decode('utf-8')
        except Exception as e:
            raise InvalidDataError(f"Ошибка при сериализации данных: {e}")

    def deserialize(self, data: str):
        try:
            if self.format == 'json':
                import json
                return json.loads(data)
            elif self.format == 'xml':
                from xmltodict import xmltodict
                return xmltodict.parse(data)
        except Exception as e:
            raise InvalidDataError(f"Ошибка при десериализации данных: {e}")

class MemoryEfficientObserver:
    __slots__ = ('subscribers',)

    def __init__(self):
        self.subscribers = []

    def subscribe(self, subscriber: callable):
        if subscriber not in self.subscribers:
            self.subscribers.append(subscriber)

    def unsubscribe(self, subscriber: callable):
        try:
            self.subscribers.remove(subscriber)
        except ValueError:
            print(f"Subscriber {subscriber} is not subscribed.")

    def notify(self, *args, **kwargs):
        for subscriber in self.subscribers[:]:  # Используем копию списка для безопасности
            try:
                subscriber(*args, **kwargs)
            except Exception as e:
                print(f"Error notifying subscriber {subscriber}: {e}")

