    """
    Применяет правила валидации к преобразованным данным.

    Аргументы:
    transformed_data (dict): Словарь с преобразованными данными.
    validation_rules (dict): Словарь с правилами валидации.

    Возвращает:
    bool: True, если данные соответствуют правилам; False в противном случае.
    """
    try:
        for field, rules in validation_rules.items():
            if 'required' in rules and field not in transformed_data:
                return False
            if field in transformed_data:
                value = transformed_data[field]
                if rules.get('type') and not isinstance(value, rules['type']):
                    return False
                if 'min_value' in rules and value < rules['min_value']:
                    return False
                if 'max_value' in rules and value > rules['max_value']:
                    return False
        return True
    except Exception as e:
        print(f"Ошибка при применении правил валидации: {e}")
        return False

