from collections import deque
from threading import Lock

class ThreadSafeRingBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self._buffer = deque(maxlen=capacity)
        self._lock = Lock()

    def put(self, item: any) -> None:
        """Добавляет элемент в буфер."""
        with self._lock:
            self._buffer.append(item)

    def get(self) -> any:
        """Извлекает и возвращает элемент из буфера."""
        with self._lock:
            if not self._buffer:
                raise IndexError("Buffer is empty")
            return self._buffer.popleft()

import asyncio
from typing import Any, Optional
from concurrent.futures import ThreadPoolExecutor

class ThreadPoolContextManager:
    def __init__(self, max_workers: int):
        if max_workers <= 0:
            raise ValueError("max_workers must be positive")
        self._max_workers = max_workers
        self._loop = asyncio.get_running_loop()
        self._executor: Optional[ThreadPoolExecutor] = None

    async def __aenter__(self) -> 'ThreadPoolContextManager':
        try:
            self._executor = await self._loop.run_in_executor(None, lambda: ThreadPoolExecutor(max_workers=self.max_workers))
            return self
        except Exception as e:
            raise RuntimeError(f"Failed to create thread pool executor: {e}")

    async def __aexit__(self, exc_type: Optional[type], exc_val: Optional[Exception], exc_tb: Optional[Any]) -> None:
        if self._executor:
            await self._loop.run_in_executor(None, lambda: self._executor.shutdown(wait=True))
            self._executor = None

    @property
    def max_workers(self) -> int:
        return self._max_workers

# Пример использования:
