def check_data_integrity(parsed_data: dict) -> dict:
    """
    Проверяет целостность данных после их обработки.

    Аргументы:
    parsed_data (dict): Структурированный словарь с данными из предыдущих результатов.

    Возвращает:
    dict: Отчет о проверке целостности данных.
    """
    try:
        # Инициализация отчета
        integrity_report = {
            "data_integrity": True,
            "integrity_issues": []
        }

        # Проверка наличия ключевых полей
        required_fields = ["id", "value", "timestamp"]
        for field in required_fields:
            if field not in parsed_data:
                integrity_report["data_integrity"] = False
                integrity_report["integrity_issues"].append(f"Отсутствует поле: {field}")

        # Проверка типов данных
        if not isinstance(parsed_data.get("id"), int):
            integrity_report["data_integrity"] = False
            integrity_report["integrity_issues"].append("Неверный тип данных для 'id'. Ожидается int.")

        if not isinstance(parsed_data.get("value"), float):
            integrity_report["data_integrity"] = False
            integrity_report["integrity_issues"].append("Неверный тип данных для 'value'. Ожидается float.")

        if not isinstance(parsed_data.get("timestamp"), str):
            integrity_report["data_integrity"] = False
            integrity_report["integrity_issues"].append("Неверный тип данных для 'timestamp'. Ожидается str.")

        return integrity_report

    except Exception as e:
        raise ValueError(f"Ошибка при проверке целостности данных: {str(e)}")

