import math
import mmh3
from array import array

class BloomFilter:
    __slots__ = ('_bits', '_k', '_mask')

    def __init__(self, capacity: int, error_rate: float = 0.01):
        """
        :param capacity: ожидаемое количество элементов (n)
        :param error_rate: допустимая вероятность ложного срабатывания (p)
        """
        if not (0 < error_rate < 1):
            raise ValueError("error_rate должен быть в (0, 1)")

        # Оптимальный размер битового массива: m = -n * ln(p) / (ln(2)^2)
        ln2 = math.log(2)
        m = int(-capacity * math.log(error_rate) / (ln2 * ln2))
        m = max(m, 1)

        # Оптимальное число хеш-функций: k = (m/n) * ln(2)
        k = max(1, int((m / capacity) * ln2))

        # Выравниваем m до кратного 64 для быстрых битовых операций
        self._bits = array('Q', [0]) * ((m + 63) // 64)
        self._k = k
        self._mask = (1 << 64) - 1  # Маска для 64 бит

    def _hashes(self, item) -> list[int]:
        """Генерирует k 64-битных хешей через double hashing (Kirsch-Mitzenmacher)."""
        h1 = mmh3.hash64(str(item), seed=0, signed=False)[0]
        h2 = mmh3.hash64(str(item), seed=1, signed=False)[0]
        return [(h1 + i * h2) & self._mask for i in range(self._k)]

    def add(self, item) -> None:
        for h in self._hashes(item):
            idx = h % len(self._bits)
            self._bits[idx] |= (1 << (h & 63))

    def contains(self, item) -> bool:
        for h in self._hashes(item):
            idx = h % len(self._bits)
            if not (self._bits[idx] & (1 << (h & 63))):
                return False
        return True

    def __contains__(self, item) -> bool:
        return self.contains(item)

    def __len__(self) -> int:
        """Возвращает размер битового массива в битах."""
        return len(self._bits) * 64

    @property
    def memory_bytes(self) -> int:
        """Память, занимаемая битовым массивом (без накладных расходов Python)."""
        return len(self._bits) * 8
